import { Link, useNavigate, useParams, useSearchParams } from "react-router";
import { AlertTriangle, ArrowLeft, ArrowRight, ChevronRight, FilePlus2, Loader2, MessageCircle, RefreshCw, Scale } from "lucide-react";
import { toast } from "sonner";
import { api, type CompanyDossier, type CompanyResearchOverview, type CompanyThesisEvidenceResponse, type EntryResearch, type ExitResearch, type MarketCode, type PriceBar, type RiskResearch, type TdxSecurityOverview, type ValuePriceZone, type ValuePriceZones, type ValueStrategyEventBatch, type ValueStrategyState } from "@/lib/api";
import { cn } from "@/lib/utils";
