import { DecisionFlow } from "@/components/workspace/DecisionFlow";
import { useDecisionFlow } from "@/hooks/useDecisionFlow";
import { inferReturnLabel, safeInternalPath } from "@/lib/routeContext";
import { BusinessResearchCard, CompanyResearchOverviewCard, FinancialAnalysisContent, ThesisReviewCard } from "@/pages/FinancialAnalysis";
import { CompanyResearchEvidencePanel, CompanyThesisSummaryPanel, ThesisHistoryTimeline } from "@/components/value/CompanyResearchEvidencePanels";
import { CompanyThesisDraftPanel } from "@/components/value/CompanyThesisDraftPanel";
import { CompanyWatchpointsPanel } from "@/components/value/CompanyWatchpointsPanel";
import { FinancialAgentFloat } from "@/components/value/FinancialAgentFloat";
import { RiskResearchCard } from "@/components/value/RiskResearchCard";
import { LeaderQualityProfilePanel } from "@/components/value/LeaderQualityProfilePanel";
import { MoatResearchPanel } from "@/components/value/MoatResearchPanel";
import { CapitalAllocationFactsPanel } from "@/components/value/CapitalAllocationFactsPanel";
import { confidenceLabel, entryStatusLabel, exitStatusLabel, metricLabel, thesisStatusLabel } from "@/components/value/SourceReferenceCard";
import { LazyDetails } from "@/components/value/LazyDetails";
import { ValuePriceZoneConclusionCard } from "@/components/value/ValuePriceZoneConclusionCard";
import { ownerAuthority, ownerStatus } from "@/lib/ownerLanguage";

const TABS = ["总览", "为什么是龙头", "经营与财务", "估值", "风险与待验证", "核心逻辑", "更多研究"] as const;
type Tab = typeof TABS[number];
const TAB_KEYS: Record<Tab, string> = { 总览: "overview", 为什么是龙头: "leader", 经营与财务: "operations", 估值: "valuation", 风险与待验证: "risk", 核心逻辑: "thesis", 更多研究: "more" };
function tabFromQuery(value: string | null): Tab {
  const legacy: Record<string, Tab> = {
    kline: "更多研究", sectors: "更多研究", capital: "更多研究", microstructure: "更多研究", research: "核心逻辑",
    "leader-quality": "为什么是龙头", "moat-research": "更多研究", financial: "经营与财务", "capital-allocation": "更多研究",
    business: "经营与财务", "估值与价格": "估值", "risk": "风险与待验证", evidence: "更多研究", thesis: "核心逻辑", raw: "更多研究",
  };
  if (value && legacy[value]) return legacy[value];
  return TABS.find((item) => item === value || TAB_KEYS[item] === value) || "总览";
}
const RAW_TABS = ["行情", "题材", "分红股本", "资金结构"] as const;
type RawTab = typeof RAW_TABS[number];
const RAW_TAB_KEYS: Record<RawTab, string> = { 行情: "kline", 题材: "sectors", 分红股本: "capital", 资金结构: "microstructure" };
function rawTabFromQuery(value: string | null): RawTab { return RAW_TABS.find((item) => item === value || RAW_TAB_KEYS[item] === value) || "行情"; }
type Dict = Record<string, unknown>;
function pct(value: unknown) { const n = Number(value); return Number.isFinite(n) ? `${n > 0 ? "+" : ""}${n.toFixed(2)}%` : "—"; }
function asDict(value: unknown): Dict { return value && typeof value === "object" && !Array.isArray(value) ? value as Dict : {}; }
function asRows(value: unknown): Dict[] { return Array.isArray(value) ? value.filter((item): item is Dict => Boolean(item && typeof item === "object")) : []; }

export function CompanyResearch() {
  const { market: rawMarket, symbol = "" } = useParams<{ market: string; symbol: string }>();
  const market = (rawMarket?.toUpperCase() ?? "CN") as MarketCode;
  if (market !== "CN") return <LegacyCompany market={market} symbol={symbol} />;
  return <TdxCompany symbol={symbol} />;
}

function TdxCompany({ symbol }: { symbol: string }) {
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const { flow, selectLeader, update: updateFlow } = useDecisionFlow();
  const [data, setData] = useState<TdxSecurityOverview | null>(null);
  const [dossier, setDossier] = useState<CompanyDossier | null>(null);
  const [researchOverview, setResearchOverview] = useState<CompanyResearchOverview | null>(null);
  const [thesisEvidence, setThesisEvidence] = useState<CompanyThesisEvidenceResponse | null>(null);
  const [riskResearch, setRiskResearch] = useState<RiskResearch | null>(null);
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState<"refresh" | "kline" | "research" | "committee" | null>(null);
  const [agentOpen, setAgentOpen] = useState(false);
  const tab = tabFromQuery(params.get("tab"));
  const rawTab = rawTabFromQuery(params.get("raw") || params.get("tab"));
  const [period, setPeriod] = useState("1d");
  const [dividendType, setDividendType] = useState("front");
  const load = useCallback(async () => {
    setLoading(true);
    try { setData(await api.getTdxSecurityOverview(symbol)); }
    catch { setData(null); }
    finally { setLoading(false); }
  }, [symbol]);
  useEffect(() => { void load(); api.getCompanyDossier("CN", symbol).then(setDossier).catch(() => setDossier(null)); }, [load, symbol]);
  useEffect(() => {
    setResearchOverview(null); setThesisEvidence(null); setRiskResearch(null);
    api.getCompanyResearchOverview(symbol).then(setResearchOverview).catch(() => setResearchOverview(null));
    api.getCompanyThesisEvidence(symbol).then(setThesisEvidence).catch(() => setThesisEvidence(null));
    api.getCompanyRiskResearch(symbol).then(setRiskResearch).catch(() => setRiskResearch(null));
  }, [symbol]);
  useEffect(() => { if (params.get("flow") === "1" && data && flow.symbol !== symbol) selectLeader({ symbol, name: data.name }); }, [data, flow.symbol, params, selectLeader, symbol]);

  const refresh = async () => { setRunning("refresh"); try { await api.refreshTdxSecurity(symbol); await load(); toast.success("单股行情与财务快照已更新"); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "单股更新失败"); } finally { setRunning(null); } };
  const refreshKline = async () => { setRunning("kline"); try { await api.getTdxKline({ symbol, period, count: 500, dividend_type: dividendType }); await load(); toast.success("K线缓存已更新"); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "K线更新失败"); } finally { setRunning(null); } };
  const selectTab = (nextTab: Tab) => setParams((current) => { const next = new URLSearchParams(current); next.set("tab", TAB_KEYS[nextTab]); if (nextTab !== "更多研究") next.delete("raw"); return next; });
  const selectRawTab = (nextRawTab: RawTab) => setParams((current) => { const next = new URLSearchParams(current); next.set("tab", "raw"); next.set("raw", RAW_TAB_KEYS[nextRawTab]); return next; });
  const research = async () => { setRunning("research"); try { const result = await api.researchCompany("CN", symbol); setDossier(result.dossier); selectTab("核心逻辑"); updateFlow({ research_report_id: result.report?.id, research_completed_at: new Date().toISOString() }); toast.success("深度研究底稿已生成，可在更多研究中查看"); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "研究失败"); } finally { setRunning(null); } };
  const committee = async () => { setRunning("committee"); try { const result = await api.createCommittee({ market: "CN", symbol, company_name: data?.name || dossier?.name || symbol }); navigate(`/committee/${result.id}`); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "启动投委会失败"); } finally { setRunning(null); } };
  const viewResearchState = () => navigate("/value/opportunities");

  if (loading) return <WorkspacePage><CompanyNavigation symbol={symbol} /><LoadingState label="正在读取通达信缓存…" /></WorkspacePage>;
  if (!data) return <WorkspacePage><CompanyNavigation symbol={symbol} /><EmptyState title="未找到A股证券" body="请先在数据中心更新实时行情；公司详情不会自动触发全市场财务更新。" /></WorkspacePage>;
  const detail = asDict(data.detail);
  const snapshot = asDict(detail.snapshot);
  const extended = asDict(detail.extended);
  return <WorkspacePage><CompanyNavigation symbol={symbol} companyName={data.name} />
    <PageHeader eyebrow={`A-SHARE / ${data.code}`} title={`${data.name} · 公司研究`} description={`${params.get("sector_name") || flow.sector_name ? `所属研究行业：${params.get("sector_name") || flow.sector_name} · ` : ""}${data.source} · 数据时间（北京时间）${new Date(data.as_of).toLocaleString("zh-CN", { hour12: false })}`} actions={<><Link to="/ai/agent" className="inline-flex items-center gap-1.5 rounded-md bg-primary px-2.5 py-1.5 text-xs font-medium text-primary-foreground"><MessageCircle className="h-3.5 w-3.5" />问投研主管</Link><details className="relative"><summary className="cursor-pointer list-none rounded-md border bg-card px-2.5 py-1.5 text-xs font-medium">专项研究</summary><div className="absolute right-0 z-10 mt-2 flex min-w-44 flex-col gap-1 rounded-lg border bg-card p-2 shadow-lg"><button onClick={() => setAgentOpen(true)} className="rounded px-2 py-1.5 text-left text-xs hover:bg-muted">问财报研究员</button><button onClick={() => selectTab("估值")} className="rounded px-2 py-1.5 text-left text-xs hover:bg-muted">查看估值资料</button><button onClick={() => selectTab("风险与待验证")} className="rounded px-2 py-1.5 text-left text-xs hover:bg-muted">查看风险资料</button></div></details><button onClick={() => void refresh()} disabled={Boolean(running)} className="inline-flex items-center gap-1.5 rounded-md border bg-card px-2.5 py-1.5 text-xs font-medium"><RefreshCw className={cn("h-3.5 w-3.5", running === "refresh" && "animate-spin")} />刷新</button><button onClick={() => void research()} disabled={Boolean(running)} className="inline-flex items-center gap-1.5 rounded-md border bg-card px-2.5 py-1.5 text-xs font-medium">{running === "research" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <FilePlus2 className="h-3.5 w-3.5" />}生成底稿</button><button onClick={() => void committee()} disabled={Boolean(running)} className="inline-flex items-center gap-1.5 rounded-md border bg-card px-2.5 py-1.5 text-xs font-medium">{running === "committee" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Scale className="h-3.5 w-3.5" />}投委会</button></>} />
    <details className="rounded-lg border bg-card px-3 py-2 text-sm"><summary className="cursor-pointer font-medium">研究流程</summary><div className="pt-3"><DecisionFlow current={4} /></div></details>
    {data.cache?.stale ? <div className="flex items-center gap-2 rounded-xl border border-warning/30 bg-warning/5 p-3 text-sm text-warning"><AlertTriangle className="h-4 w-4" />行情缓存已超过15分钟</div> : null}
    <ResearchDataTransparency overview={researchOverview} thesisEvidence={thesisEvidence} riskResearch={riskResearch} priceAsOf={data.as_of} />
    <div className="overflow-x-auto"><div role="tablist" aria-label="公司详情内容" className="inline-flex min-w-max rounded-lg border bg-card p-1">{TABS.map((item) => <button role="tab" aria-selected={tab === item} key={item} onClick={() => selectTab(item)} className={cn("rounded-md px-4 py-2 text-sm", tab === item ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground")}>{item}</button>)}</div></div>
    {tab === "总览" ? <><CompanyResearchConclusionCard stockCode={symbol} /><OverviewTab symbol={symbol} overview={researchOverview} riskResearch={riskResearch} thesisEvidence={thesisEvidence} onGoValuation={() => selectTab("估值")} /></> : null}
    {tab === "为什么是龙头" ? <LeaderQualityProfilePanel stockCode={symbol} asOf={params.get("as_of") || undefined} compact /> : null}
    {tab === "经营与财务" ? <OperationsFinancialTab stockCode={symbol} asOf={params.get("as_of") || undefined} /> : null}
    {tab === "估值" ? <ValuationTab stockCode={symbol} /> : null}
    {tab === "风险与待验证" ? <RiskAndValidationTab stockCode={symbol} asOf={params.get("as_of") || undefined} /> : null}
    {tab === "核心逻辑" ? <CoreThesisTab symbol={symbol} dossier={dossier} running={running === "research"} reportId={flow.research_report_id} onResearch={() => void research()} onCreatePlan={viewResearchState} /> : null}
    {tab === "更多研究" ? <MoreResearchTab symbol={symbol} asOf={params.get("as_of") || undefined} rawTab={rawTab} onSelectRaw={selectRawTab} data={data} period={period} setPeriod={setPeriod} dividendType={dividendType} setDividendType={setDividendType} refresh={() => void refreshKline()} loading={running === "kline"} detail={detail} snapshot={snapshot} extended={extended} dossier={dossier} running={running === "research"} reportId={flow.research_report_id} onResearch={() => void research()} onCreatePlan={viewResearchState} /> : null}
    <FinancialAgentFloat open={agentOpen} target={{ stock_code: symbol, stock_name: data.name, as_of: data.as_of, level3_name: "当前公司" }} onClose={() => setAgentOpen(false)} />
  </WorkspacePage>;
}

function CompanyResearchConclusionCard({ stockCode }: { stockCode: string }) {
  const [data, setData] = useState<ValueStrategyState | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { setLoading(true); setError(""); api.getValueStrategyState(stockCode).then(setData).catch((reason) => setError(reason instanceof Error ? reason.message : String(reason))).finally(() => setLoading(false)); }, [stockCode]);
  if (loading) return <section className="rounded-xl border border-primary/25 bg-card p-5 text-sm text-muted-foreground"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />整理当前研究状态…</section>;
  if (error || !data) return <section className="rounded-xl border bg-card p-5"><h2 className="font-semibold">当前研究状态</h2><p className="mt-2 text-sm text-muted-foreground">{error || "当前资料暂不可用。"}</p></section>;
  const attentionTone = data.price_attention.effective_status === "HIGH_ATTENTION" || data.price_attention.effective_status === "ATTENTION" ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-700" : data.price_attention.effective_status.includes("REVIEW") ? "border-amber-500/40 bg-amber-500/10 text-amber-800" : "border-muted bg-muted/40 text-muted-foreground";
  const reviewTone = ["CRITICAL_REVIEW", "REVIEW"].includes(data.review_pressure.effective_status) ? "border-red-500/40 bg-red-500/10 text-red-700" : "border-muted bg-muted/40 text-muted-foreground";
  return <section className="rounded-xl border border-primary/35 bg-card p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-medium text-primary">VALUE STRATEGY STATE</div><h2 className="mt-1 text-lg font-semibold">当前研究状态</h2><p className="mt-1 text-sm text-muted-foreground">{data.stock_name || stockCode} · {data.stock_code}</p></div><span className="rounded bg-primary/10 px-2 py-1 text-xs text-primary">{data.primary_action.label}</span></div><p className="mt-4 rounded-lg bg-muted/40 p-3 text-sm leading-6">{data.summary}</p><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article className="rounded-lg border p-3"><div className="text-xs text-muted-foreground">研究资格</div><strong className="mt-1 block text-sm">{data.eligibility.label}</strong></article><article className="rounded-lg border p-3"><div className="text-xs text-muted-foreground">研究优先级</div><strong className="mt-1 block text-sm">{data.priority.label}</strong></article><article className={cn("rounded-lg border p-3", attentionTone)}><div className="text-xs opacity-75">价格与估值关注条件</div><strong className="mt-1 block text-sm">{data.price_attention.primary ? data.price_attention.effective_label : "仅作为详细资料参考"}</strong></article><article className={cn("rounded-lg border p-3", reviewTone)}><div className="text-xs opacity-75">研究复核压力</div><strong className="mt-1 block text-sm">{data.review_pressure.primary ? data.review_pressure.effective_label : "仅作为详细资料参考"}</strong></article></div><div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-xs text-muted-foreground"><span>研究日期：{data.research_as_of || "资料不足"}</span><span>现价日期：{data.freshness.market_price_as_of || "资料不足"}</span><span>低估池日期：{data.freshness.low_value_as_of || "资料不足"}</span><span>估值可靠性：{data.price_attention.valuation_reliability.label}</span></div><RecentResearchChanges stockCode={stockCode} />{data.freshness.notice ? <p className="mt-3 rounded border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-800">{data.freshness.notice}</p> : null}<details className="mt-4 rounded-lg border"><summary className="cursor-pointer px-3 py-2 text-xs font-medium">查看计算依据</summary><div className="space-y-2 border-t p-3 text-xs text-muted-foreground"><p>价格关注原始结果：{data.price_attention.raw_label}；估值可靠性：{data.price_attention.valuation_reliability.label}。</p><p>研究复核压力：{data.review_pressure.effective_label}；风险：{data.risk.overall === "HIGH" ? "高" : data.risk.overall === "MEDIUM" ? "中" : data.risk.overall === "LOW" ? "低" : "资料不足"}。</p>{data.price_attention.cautions.map((item) => <p key={item}>注意：{item}</p>)}</div></details></section>;
}

function RecentResearchChanges({ stockCode }: { stockCode: string }) {
  const [items, setItems] = useState<ValueStrategyEventBatch[]>([]);
  useEffect(() => { api.getValueStrategyEventBatches(stockCode, 5).then((value) => setItems(value.items)).catch(() => setItems([])); }, [stockCode]);
  const label = (severity: string) => ({ CRITICAL: "需立即复核", HIGH: "重点处理", MEDIUM: "需要关注", INFO: "资料更新" } as Record<string, string>)[severity] || "资料更新";
  const update = async (item: ValueStrategyEventBatch, action: "ack" | "close") => { const id = item.event_ids[0]; if (!id) return; await (action === "ack" ? api.acknowledgeValueStrategyEvent(id) : api.closeValueStrategyEvent(id)); const value = await api.getValueStrategyEventBatches(stockCode, 5); setItems(value.items); };
  return <section className="mt-4 rounded-lg border"><div className="border-b px-3 py-2 text-sm font-medium">最近研究变化</div>{items.length ? <div className="divide-y">{items.map((item) => <details key={item.transition_batch_id} className="px-3 py-2"><summary className="cursor-pointer list-none"><div className="flex items-center justify-between gap-3"><div><strong className="text-sm">{item.title}</strong><p className="mt-1 text-xs text-muted-foreground">{item.research_as_of || "资料不足"} · {item.summary}</p></div><span className="shrink-0 rounded bg-muted px-2 py-1 text-xs">{label(item.severity)} · {item.status === "OPEN" ? "待处理" : item.status === "ACKNOWLEDGED" ? "已确认" : "已关闭"}</span></div></summary><div className="mt-2 border-t pt-2 text-xs text-muted-foreground"><p>主要原因：{item.primary_reason}</p>{item.simultaneous_changes.length ? <p className="mt-1">同时发生：{item.simultaneous_changes.join("；")}</p> : null}{item.status !== "CLOSED" ? <div className="mt-2 flex gap-2"><button className="rounded border px-2 py-1" onClick={() => void update(item, "ack")}>确认</button><button className="rounded border px-2 py-1" onClick={() => void update(item, "close")}>关闭</button></div> : null}</div></details>)}</div> : <p className="px-3 py-4 text-sm text-muted-foreground">上线以来尚无已记录的研究状态变化。</p>}</section>;
}

function ResearchDataTransparency({ overview, thesisEvidence, riskResearch, priceAsOf }: { overview: CompanyResearchOverview | null; thesisEvidence: CompanyThesisEvidenceResponse | null; riskResearch: RiskResearch | null; priceAsOf: string }) {
  const authority = ownerAuthority(thesisEvidence?.current_thesis?.authority_status);
  const researchDate = overview?.financial_summary.as_of || overview?.business_summary.data_as_of || "资料不足";
  return <section className="rounded-lg border bg-card px-4 py-3"><div className="flex flex-wrap gap-x-5 gap-y-2 text-xs"><span><span className="text-muted-foreground">研究日期：</span>{researchDate}</span><span><span className="text-muted-foreground">价格实际日期：</span>{priceAsOf ? new Date(priceAsOf).toLocaleString("zh-CN", { hour12: false }) : "资料不足"}</span><span><span className="text-muted-foreground">财务最新公告：</span>{overview?.financial_summary.latest_announcement_date || "资料不足"}</span><span><span className="text-muted-foreground">财务资料：</span>{ownerStatus(overview?.financial_summary.status)}</span><span><span className="text-muted-foreground">经营资料：</span>{ownerStatus(overview?.business_summary.status)}</span><span><span className="text-muted-foreground">风险资料：</span>{ownerStatus(riskResearch?.status)}</span><span><span className="text-muted-foreground">核心逻辑：</span>{authority}</span></div></section>;
}

function ZoneRange({ zone }: { zone: ValuePriceZone }) { return <span>{zone.low == null ? "低于 " : ""}{zone.low == null ? formatNumber(zone.high) : zone.high == null ? `高于 ${formatNumber(zone.low)}` : `${formatNumber(zone.low)}–${formatNumber(zone.high)}`}</span>; }

function PriceZoneCard({ stockCode }: { stockCode: string }) {
  const [data, setData] = useState<ValuePriceZones | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { setLoading(true); setError(""); api.getCompanyPriceZones(stockCode).then(setData).catch((reason) => setError(reason instanceof Error ? reason.message : String(reason))).finally(() => setLoading(false)); }, [stockCode]);
  if (loading) return <section className="rounded-xl border bg-card p-5 text-sm text-muted-foreground"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />读取估值与价格位置…</section>;
  if (error || !data) return <section className="rounded-xl border bg-card p-5"><h2 className="font-semibold">估值与价格位置</h2><p className="mt-2 text-sm text-muted-foreground">{error || "当前资料暂不可用。"}</p></section>;
  const valuation = data.valuation;
  const zones = (title: string, items: ValuePriceZone[], empty: string) => <article className="rounded-lg border border-border p-4"><h3 className="text-sm font-semibold">{title}</h3>{items.length ? <div className="mt-3 space-y-2">{items.slice(0, 3).map((zone, index) => <div key={`${zone.low}-${zone.high}-${index}`} className="rounded bg-muted/30 p-2 text-sm"><div className="flex justify-between gap-2"><strong><ZoneRange zone={zone} /></strong>{zone.strength ? <span className="text-xs text-muted-foreground">{zone.strength === "HIGH" ? "强" : zone.strength === "MEDIUM" ? "一般" : "较弱"}</span> : null}</div>{zone.reasons?.length ? <p className="mt-1 text-xs leading-5 text-muted-foreground">{zone.reasons.slice(0, 2).join("；")}</p> : null}</div>)}</div> : <p className="mt-3 text-sm text-muted-foreground">{empty}</p>}</article>;
  const historical = data.historical_valuation;
  const historicalMetric = (label: string, metric: keyof NonNullable<ValuePriceZones["historical_valuation"]>["historical_percentiles"]) => {
    const value = historical?.historical_percentiles[metric];
    return <article className="rounded-lg border border-border p-3" key={metric}><div className="text-xs text-muted-foreground">{label}</div>{value?.status === "READY" ? <><strong className="mt-1 block text-base tabular-nums">{formatNumber(value.current)} · {Math.round(value.percentile || 0)}%</strong><p className="mt-1 text-xs leading-5 text-muted-foreground">{value.plain}</p></> : <p className="mt-2 text-sm text-muted-foreground">历史估值数据不足，暂时不能判断。</p>}</article>;
  };
  const midpoint = valuation.fair_value_mid;
  const distance = data.current_price != null && midpoint != null && midpoint !== 0 ? (midpoint - data.current_price) / midpoint : null;
  const metrics = historical?.historical_percentiles;
  return <section className="rounded-xl border border-primary/25 bg-card p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="text-xs font-medium text-primary">估值与价格</div><h2 className="mt-1 text-lg font-semibold">估值与价格位置</h2><p className="mt-1 text-xs text-muted-foreground">先判断是否接近值得关注的价值区域；不产生交易指令。</p></div><span className="rounded bg-muted px-2 py-1 text-xs text-muted-foreground">数据截至 {data.as_of || "—"}</span></div><div className="mt-4 grid gap-3 sm:grid-cols-4"><div className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">当前价格</div><strong className="mt-1 block text-lg tabular-nums">{formatNumber(data.current_price)}</strong></div><div className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">合理价值中枢</div><strong className="mt-1 block text-lg tabular-nums">{formatNumber(midpoint)}</strong></div><div className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">合理价值区间</div><strong className="mt-1 block text-lg tabular-nums">{valuation.fair_value_low == null ? "资料不足" : `${formatNumber(valuation.fair_value_low)}–${formatNumber(valuation.fair_value_high)}`}</strong></div><div className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">距离中枢</div><strong className="mt-1 block text-lg">{distance == null ? "资料不足" : `${distance >= 0 ? "低于" : "高于"} ${Math.abs(distance * 100).toFixed(1)}%`}</strong></div></div><div className="mt-3 grid gap-3 sm:grid-cols-3"><div className="rounded-lg border border-border p-3 text-sm"><span className="text-muted-foreground">PE</span><strong className="ml-2">{metrics?.pe_ttm?.current == null ? "资料不足" : `${formatNumber(metrics.pe_ttm.current)} 倍`}</strong></div><div className="rounded-lg border border-border p-3 text-sm"><span className="text-muted-foreground">PB</span><strong className="ml-2">{metrics?.pb_mrq?.current == null ? "资料不足" : `${formatNumber(metrics.pb_mrq.current)} 倍`}</strong></div><div className="rounded-lg border border-border p-3 text-sm"><span className="text-muted-foreground">股息率</span><strong className="ml-2">{metrics?.dividend_yield?.current == null ? "资料不足" : `${formatNumber(metrics.dividend_yield.current)}%`}</strong></div></div><p className="mt-4 text-sm leading-6">{data.plain_summary}</p><LazyDetails className="mt-4 rounded-lg border border-border" summary="查看历史估值位置"><div className="border-t p-4"><div className="grid gap-3 md:grid-cols-3">{historicalMetric("PE（越低通常越便宜）", "pe_ttm")}{historicalMetric("PB（越低通常越便宜）", "pb_mrq")}{historicalMetric("股息率（越高通常越便宜）", "dividend_yield")}</div></div></LazyDetails><LazyDetails className="mt-3 rounded-lg border border-border" summary="查看支撑、压力与重合区域"><div className="space-y-3 border-t p-4"><div className="grid gap-3 lg:grid-cols-2">{zones("历史主要支撑", data.support_zones, data.data_quality.daily_history.message || "历史日线不足，暂不计算支撑区。")}{zones("历史主要压力", data.resistance_zones, data.data_quality.daily_history.message || "历史日线不足，暂不计算压力区。")}</div><div className="grid gap-3 lg:grid-cols-2">{zones("价值与支撑重叠关注区", data.confluence_zones, "当前没有形成可解释的重叠区。")}{zones("偏高估值与压力重叠区", data.upper_review_zones, "当前没有形成需要复核的上方重叠区。")}</div></div></LazyDetails><LazyDetails className="mt-3 rounded-lg border border-border" summary="查看计算说明与数据边界"><div className="space-y-1 border-t p-3 text-xs leading-5 text-muted-foreground"><p>估值方法：{valuation.methods.map((method) => `${method.name}${method.peer_count ? `（可比 ${method.peer_count} 家）` : ""}`).join("；") || "资料不足"}。</p><p>历史估值：{data.data_quality.historical_valuation.message}</p><p>PE/PB 仅使用交易日已公告的财务数据；股息率以通达信除权日作为保守可见日期。</p></div></LazyDetails></section>;
}

function EntryResearchCard({ stockCode }: { stockCode: string }) {
  const [data, setData] = useState<EntryResearch | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { setLoading(true); setError(""); api.getCompanyEntryResearch(stockCode).then(setData).catch((reason) => setError(reason instanceof Error ? reason.message : String(reason))).finally(() => setLoading(false)); }, [stockCode]);
  if (loading) return <section className="rounded-xl border bg-card p-5 text-sm text-muted-foreground"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />整理价格与估值关注条件…</section>;
  if (error || !data) return <section className="rounded-xl border bg-card p-5"><h2 className="font-semibold">入场研究原始档（计算明细）</h2><p className="mt-2 text-sm text-muted-foreground">{error || "当前资料暂不可用。"}</p></section>;
  const focus = data.focus_zones.focus_zone;
  const reasonLabels: Record<string, string> = {
    VALUATION_DEEPLY_UNDERVALUED: "当前估值明显低于合理区间", VALUATION_UNDERVALUED: "当前估值低于合理区间", VALUATION_FAIR: "当前估值处在合理区间", VALUATION_OVERVALUED: "当前估值偏高", VALUATION_DEEPLY_OVERVALUED: "当前估值明显偏高",
    HISTORICAL_VALUATION_VERY_CHEAP: "历史估值处于很低位置", HISTORICAL_VALUATION_CHEAP: "历史估值处于较低位置", HISTORICAL_VALUATION_EXPENSIVE: "历史估值偏高", HISTORICAL_VALUATION_VERY_EXPENSIVE: "历史估值明显偏高",
    VALUATION_SUPPORT_CONFLUENCE: "价值区与历史支撑区形成重叠", HIGH_SUPPORT: "接近历史强支撑", MEDIUM_SUPPORT: "接近历史中等强度支撑", HISTORICAL_SUPPORT: "接近历史支撑", NEAR_RESISTANCE: "同时接近历史压力", THESIS_STRENGTHENING: "公司逻辑正在增强", THESIS_UNCHANGED: "公司逻辑基本稳定", THESIS_FORMING: "公司逻辑仍在形成", THESIS_WEAKENING: "公司逻辑正在减弱", THESIS_FALSIFIED: "公司核心逻辑已失效", DATA_PARTIAL: "关键数据尚不完整",
  };
  const levelTone: Record<string, string> = { HIGH_ATTENTION: "border-emerald-500/40 bg-emerald-500/10 text-emerald-700", ATTENTION: "border-blue-500/40 bg-blue-500/10 text-blue-700", WATCH: "border-amber-500/40 bg-amber-500/10 text-amber-700", WAIT: "border-muted bg-muted/40 text-muted-foreground", BLOCKED: "border-red-500/40 bg-red-500/10 text-red-700" };
  const range = (zone: EntryResearch["focus_zones"][string] | undefined) => !zone ? "当前没有明确区间" : zone.low == null ? `低于 ${formatNumber(zone.high)}` : zone.high == null ? `高于 ${formatNumber(zone.low)}` : `${formatNumber(zone.low)}–${formatNumber(zone.high)}`;
  return <section className="rounded-xl border border-primary/25 bg-card p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-medium text-primary">入场研究</div><h2 className="mt-1 text-lg font-semibold">入场研究原始档（计算明细）</h2><p className="mt-1 text-xs text-muted-foreground">只解释估值、历史位置、价格结构与核心逻辑条件，是计算明细，不是主结论。</p></div><span className={cn("rounded border px-3 py-1.5 text-sm font-semibold", levelTone[data.entry_level])}>{entryStatusLabel(data.entry_level)}</span></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><article className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">重点观察区</div><strong className="mt-1 block text-lg tabular-nums">{range(focus)}</strong></article><article className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">较高安全边际区</div><strong className="mt-1 block text-lg tabular-nums">{range(data.focus_zones.high_margin_zone)}</strong></article><article className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">研究置信度</div><strong className="mt-1 block text-lg">{confidenceLabel(data.confidence)}</strong></article></div><p className="mt-4 text-sm leading-6">{data.plain_explanation}</p><div className="mt-3 flex flex-wrap gap-2">{data.reason_codes.slice(0, 5).map((code) => <span key={code} className="rounded-full bg-muted px-2 py-1 text-xs text-muted-foreground">{reasonLabels[code] || code}</span>)}</div><details className="mt-4 rounded-lg border border-border"><summary className="cursor-pointer px-3 py-2 text-xs font-medium">查看计算依据与数据边界</summary><div className="grid gap-3 border-t p-3 text-xs sm:grid-cols-4"><div>当前价值：<strong>{data.valuation_score}</strong></div><div>历史估值：<strong>{data.historical_valuation_score}</strong></div><div>价格结构：<strong>{data.support_score}</strong></div><div>公司核心逻辑：<strong>{data.thesis_score}</strong></div><div className="sm:col-span-4 text-muted-foreground">原始计算 {data.entry_score} · 当前逻辑 {thesisStatusLabel(data.thesis_status)}{data.safety_gate ? ` · 安全门 ${data.safety_gate}` : ""}{data.data_gaps.length ? ` · 待补资料：${data.data_gaps.join("、")}` : ""}</div></div></details></section>;
}

function ExitResearchCard({ stockCode }: { stockCode: string }) {
  const [data, setData] = useState<ExitResearch | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { setLoading(true); setError(""); api.getCompanyExitResearch(stockCode).then(setData).catch((reason) => setError(reason instanceof Error ? reason.message : String(reason))).finally(() => setLoading(false)); }, [stockCode]);
  if (loading) return <section className="rounded-xl border bg-card p-5 text-sm text-muted-foreground"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />整理研究复核压力…</section>;
  if (error || !data) return <section className="rounded-xl border bg-card p-5"><h2 className="font-semibold">复核压力原始档（计算明细）</h2><p className="mt-2 text-sm text-muted-foreground">{error || "当前资料暂不可用。"}</p></section>;
  const focus = data.focus_zones.focus_zone;
  const range = (zone: ExitResearch["focus_zones"][string] | undefined) => !zone ? "当前没有明确区间" : zone.low == null ? "低于 " + formatNumber(zone.high) : zone.high == null ? "高于 " + formatNumber(zone.low) : formatNumber(zone.low) + "–" + formatNumber(zone.high);
  const tone: Record<string, string> = { CRITICAL_REVIEW: "border-red-500/40 bg-red-500/10 text-red-700", REVIEW: "border-orange-500/40 bg-orange-500/10 text-orange-700", WATCH: "border-amber-500/40 bg-amber-500/10 text-amber-700", NORMAL: "border-muted bg-muted/40 text-muted-foreground" };
  const reasons: Record<string, string> = { VALUATION_DEEPLY_OVERVALUED: "当前估值明显偏高", VALUATION_OVERVALUED: "当前估值偏高", VALUATION_FAIR: "当前估值仍在合理区间", HISTORICAL_VALUATION_VERY_EXPENSIVE: "历史估值也处在很高位置", HISTORICAL_VALUATION_EXPENSIVE: "历史估值处在较高位置", VALUATION_RESISTANCE_CONFLUENCE: "高估区与历史压力区重叠", HIGH_RESISTANCE: "接近历史强压力", MEDIUM_RESISTANCE: "接近历史中等强度压力", NEAR_RESISTANCE: "接近历史压力", THESIS_WEAKENING: "公司逻辑正在减弱", THESIS_FALSIFIED: "公司核心逻辑已失效", MULTIPLE_CHALLENGES: "存在多条挑战当前逻辑的研究证据", CHALLENGE_EVIDENCE: "存在挑战当前逻辑的研究证据", REVIEW_STALE: "已有新研究证据，研究复核已过期", DATA_PARTIAL: "关键数据尚不完整" };
  return <section className="rounded-xl border border-primary/25 bg-card p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-medium text-primary">研究复核</div><h2 className="mt-1 text-lg font-semibold">复核压力原始档（计算明细）</h2><p className="mt-1 text-xs text-muted-foreground">识别需要重新检查估值、价格压力和公司核心逻辑的情况，只提示复核，不构成任何行动指令。</p></div><span className={cn("rounded border px-3 py-1.5 text-sm font-semibold", tone[data.exit_level])}>{exitStatusLabel(data.exit_level)}</span></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><article className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">重点复核区</div><strong className="mt-1 block text-lg tabular-nums">{range(focus)}</strong></article><article className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">合理价值上沿</div><strong className="mt-1 block text-lg tabular-nums">{range(data.focus_zones.fair_value_high)}</strong></article><article className="rounded-lg border border-border p-3"><div className="text-xs text-muted-foreground">研究置信度</div><strong className="mt-1 block text-lg">{confidenceLabel(data.confidence)}</strong></article></div><p className="mt-4 text-sm leading-6">{data.plain_explanation}</p>{data.latest_review?.is_stale ? <p className="mt-3 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-800">已有新的研究证据，当前研究复核已过期，需要重新评估。</p> : null}<div className="mt-3 flex flex-wrap gap-2">{data.reason_codes.slice(0, 5).map((code) => <span key={code} className="rounded-full bg-muted px-2 py-1 text-xs text-muted-foreground">{reasons[code] || code}</span>)}</div>{data.challenge_evidence.length ? <div className="mt-4 rounded-lg border border-border p-3"><h3 className="text-sm font-semibold">需要注意的研究证据</h3><div className="mt-2 space-y-2">{data.challenge_evidence.map((item) => <div key={item.evidence_id} className="text-sm leading-6"><span className="mr-2 rounded bg-muted px-1.5 py-0.5 text-xs text-muted-foreground">{confidenceLabel(item.confidence)}置信度</span>{item.text}</div>)}</div></div> : null}<details className="mt-4 rounded-lg border border-border"><summary className="cursor-pointer px-3 py-2 text-xs font-medium">查看复核压力与数据边界</summary><div className="grid gap-3 border-t p-3 text-xs sm:grid-cols-4"><div>当前估值：<strong>{data.valuation_pressure}</strong></div><div>历史估值：<strong>{data.historical_valuation_pressure}</strong></div><div>历史压力：<strong>{data.resistance_pressure}</strong></div><div>公司核心逻辑：<strong>{data.thesis_risk}</strong></div><div className="sm:col-span-4 text-muted-foreground">原始计算 {data.exit_score} · 挑战当前逻辑的研究证据 {data.challenge_count} 条{data.safety_gate ? <span> · 安全门 {data.safety_gate}</span> : null}{data.data_gaps.length ? <span> · 待补资料：{data.data_gaps.join("、")}</span> : null}</div></div></details></section>;
}

function LegacyOverviewTab({ symbol, quote, finance, snapshot }: { symbol: string; quote: Dict; finance: Dict; snapshot: Dict }) {
  const change = Number(quote.change_pct);
  return <><CompanyResearchConclusionCard stockCode={symbol} /><CompanyResearchOverviewCard stockCode={symbol} /><PriceZoneCard stockCode={symbol} /><EntryResearchCard stockCode={symbol} /><ExitResearchCard stockCode={symbol} /><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><MetricCard label="现价（元）" value={formatNumber(quote.price)} tone={change > 0 ? "positive" : change < 0 ? "negative" : undefined} /><MetricCard label="涨跌幅" value={pct(change)} tone={change > 0 ? "positive" : change < 0 ? "negative" : undefined} /><MetricCard label="开 / 高 / 低" value={`${formatNumber(snapshot.Open)} / ${formatNumber(snapshot.Max)} / ${formatNumber(snapshot.Min)}`} /><MetricCard label="成交量（手）" value={formatNumber(quote.volume_lots, 0)} /><MetricCard label="成交额（万元）" value={formatNumber(snapshot.Amount)} /><MetricCard label="换手率" value={pct(finance.turnover_rate)} /></section>
     <section className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><article className="rounded-xl border bg-card p-5 shadow-sm"><h2 className="font-semibold">核心财务与估值</h2><div className="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["总市值", `${formatNumber(finance.market_cap_100m)}亿元`], ["营收", `${formatNumber(finance.revenue_10k)}万元`], ["净利润", `${formatNumber(finance.net_profit_10k)}万元`], ["EPS", formatNumber(finance.eps)], ["PE(TTM)", formatNumber(finance.pe_ttm)], ["PB", formatNumber(finance.pb_mrq)], ["股息率", pct(finance.dividend_yield)], ["报告日期", formatDate(finance.report_date)]].map(([label, value]) => <div key={label}><div className="text-xs text-muted-foreground">{label}</div><div className="mt-1 font-mono font-medium">{value}</div></div>)}</div></article><article className="rounded-xl border bg-card p-5 shadow-sm"><h2 className="font-semibold">盘口快照</h2>{snapshot.ItemNum ? <div className="mt-4 grid grid-cols-2 gap-3 text-sm">{[["内盘", snapshot.Inside], ["外盘", snapshot.Outside], ["均价", snapshot.AvgPrice], ["现量", snapshot.NowVol], ["买一", asRows(snapshot.BuyPrice)[0] ?? snapshot.BuyPrice], ["卖一", asRows(snapshot.SellPrice)[0] ?? snapshot.SellPrice]].map(([label, value]) => <div key={String(label)} className="rounded-lg bg-muted/50 p-3"><div className="text-xs text-muted-foreground">{String(label)}</div><div className="mt-1 font-mono">{Array.isArray(value) ? String(value[0] ?? "—") : String(value ?? "—")}</div></div>)}</div> : <p className="mt-4 text-sm text-muted-foreground">暂无盘口数据</p>}</article></section></>;
}
void LegacyOverviewTab;

function CompactOverviewTab({ symbol, overview, riskResearch, thesisEvidence, onGoValuation }: { symbol: string; overview: CompanyResearchOverview | null; riskResearch: RiskResearch | null; thesisEvidence: CompanyThesisEvidenceResponse | null; onGoValuation: () => void }) {
  const [zones, setZones] = useState<ValuePriceZones | null>(null);
  const [error, setError] = useState("");
  const [strategy, setStrategy] = useState<ValueStrategyState | null>(null);
  useEffect(() => {
    setZones(null); setError(""); setStrategy(null);
    api.getCompanyPriceZones(symbol)
      .then(setZones)
      .catch((reason) => setError(reason instanceof Error ? reason.message : String(reason)));
    api.getValueStrategyState(symbol).then(setStrategy).catch(() => setStrategy(null));
  }, [symbol]);
  if (error) return <section className="rounded-xl border border-danger/30 bg-danger/10 p-5 text-sm text-danger">读取研究摘要失败：{error}</section>;
  if (!overview || !zones) return <section className="rounded-xl border border-border bg-card p-5 text-sm text-muted-foreground"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />读取公司研究摘要…</section>;
  const business = overview.business_summary;
  const financialItems = overview.financial_summary.items.slice(0, 5);
  const pe = zones.historical_valuation?.historical_percentiles.pe_ttm;
  const midpoint = zones.valuation.fair_value_mid;
  const distance = zones.current_price != null && midpoint != null && midpoint !== 0 ? (midpoint - zones.current_price) / midpoint : null;
  const authority = ownerAuthority(thesisEvidence?.current_thesis?.authority_status);
  const gapText = (overview.data_gaps || []).slice(0, 2).map((item) => item.description).join("；");
  return <div className="space-y-4">{strategy ? <div className="flex flex-wrap items-center gap-x-4 gap-y-1 rounded-lg border bg-card px-4 py-2.5 text-sm"><span><span className="text-muted-foreground">价值范围：</span>{strategy.eligibility.status === "IN_VALUE_SCOPE" ? "在范围内" : "不在范围内"}</span><span><span className="text-muted-foreground">价格条件：</span>{strategy.price_attention.effective_label}</span><span><span className="text-muted-foreground">主动作：</span>{strategy.primary_action.label}</span><button type="button" onClick={onGoValuation} className="text-primary underline-offset-2 hover:underline">查看价格区</button></div> : null}<CompanyWatchpointsPanel stockCode={symbol} compact /><section className="grid gap-4 xl:grid-cols-3"><article className="rounded-xl border border-border bg-card p-5"><h2 className="font-semibold">公司经营摘要</h2><p className="mt-3 text-sm leading-6">{business.description || business.main_business || "目前还没有完整经营研究资料。"}</p><div className="mt-3 space-y-2 text-sm"><p><span className="text-muted-foreground">主要产品：</span>{business.products?.slice(0, 4).join("、") || "资料不足"}</p><p><span className="text-muted-foreground">最近变化：</span>{business.changes.slice(0, 2).join("；") || "尚未形成可验证的经营变化。"}</p><p><span className="text-muted-foreground">当前资料缺口：</span>{gapText || "暂无额外资料缺口。"}</p></div></article><article className="rounded-xl border border-border bg-card p-5"><h2 className="font-semibold">财务与研究风险</h2>{financialItems.length ? <ul className="mt-3 space-y-2 text-sm leading-6">{financialItems.map((item, index) => <li key={`${item.category}-${index}`}><span className="text-muted-foreground">{metricLabel(item.category)}：</span>{item.text}</li>)}</ul> : <p className="mt-3 text-sm text-muted-foreground">目前还没有可展示的财务摘要。</p>}<p className="mt-4 rounded bg-muted/40 p-2 text-xs leading-5 text-muted-foreground">最大风险：{riskResearch?.summary || "风险资料不足，暂无法完整判断。"}</p></article><article className="rounded-xl border border-border bg-card p-5"><h2 className="font-semibold">估值与核心逻辑</h2><div className="mt-3 grid grid-cols-2 gap-3 text-sm"><div><div className="text-xs text-muted-foreground">当前价格</div><strong className="mt-1 block tabular-nums">{formatNumber(zones.current_price)}</strong></div><div><div className="text-xs text-muted-foreground">合理价值中枢</div><strong className="mt-1 block tabular-nums">{formatNumber(midpoint)}</strong></div><div><div className="text-xs text-muted-foreground">距离中枢</div><strong className="mt-1 block">{distance == null ? "资料不足" : `${distance >= 0 ? "低于" : "高于"}中枢 ${Math.abs(distance * 100).toFixed(1)}%`}</strong></div><div><div className="text-xs text-muted-foreground">PE 历史位置</div><strong className="mt-1 block">{pe?.status === "READY" ? `${Math.round(pe.percentile || 0)}%` : "资料不足"}</strong></div></div><p className="mt-3 text-xs leading-5 text-muted-foreground">核心逻辑：{authority}。完整估值、风险与核心逻辑请进入对应页签。</p></article></section></div>;
}

function OverviewTab({ symbol, overview, riskResearch, thesisEvidence, onGoValuation }: { symbol: string; overview: CompanyResearchOverview | null; riskResearch: RiskResearch | null; thesisEvidence: CompanyThesisEvidenceResponse | null; onGoValuation: () => void }) { return <CompactOverviewTab symbol={symbol} overview={overview} riskResearch={riskResearch} thesisEvidence={thesisEvidence} onGoValuation={onGoValuation} />; }

function OperationsFinancialTab({ stockCode, asOf }: { stockCode: string; asOf?: string }) {
  return <div className="space-y-4"><section className="rounded-xl border border-primary/25 bg-card p-5"><div className="text-xs font-medium text-primary">经营与财务</div><h2 className="mt-1 text-lg font-semibold">公司做什么，经营和财务最近发生了什么</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">先在总览看关键结论；需要时再展开完整经营资料、财务趋势与来源。</p></section><LazyDetails open className="rounded-xl border bg-card" summary="查看经营概览与最近变化"><div className="border-t p-5"><CompanyResearchOverviewCard stockCode={stockCode} /></div></LazyDetails><LazyDetails className="rounded-xl border bg-card" summary="查看详细经营研究"><div className="border-t p-5"><BusinessResearchCard stockCode={stockCode} /></div></LazyDetails><LazyDetails className="rounded-xl border bg-card" summary="查看详细财务研究与来源"><div className="border-t p-5"><FinancialAnalysisContent stockCode={stockCode} asOf={asOf} /></div></LazyDetails></div>;
}

function ValuationTab({ stockCode }: { stockCode: string }) {
  return <div className="space-y-4"><section className="rounded-xl border border-primary/25 bg-card p-5"><div className="text-xs font-medium text-primary">估值与当前关注条件</div><h2 className="mt-1 text-lg font-semibold">先看价值位置，再看需要复核的情况</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">当前价格、合理价值与历史估值位置用于研究判断；不显示复杂评分，也不产生交易指令。</p></section><ValuePriceZoneConclusionCard stockCode={stockCode} /><LazyDetails className="rounded-xl border bg-card" summary="查看入场研究原始档（计算明细）"><div className="border-t p-5"><EntryResearchCard stockCode={stockCode} /></div></LazyDetails><LazyDetails className="rounded-xl border bg-card" summary="查看复核压力原始档（计算明细）"><div className="border-t p-5"><ExitResearchCard stockCode={stockCode} /></div></LazyDetails></div>;
}

function RiskAndValidationTab({ stockCode, asOf }: { stockCode: string; asOf?: string }) {
  return <div className="space-y-4"><section className="rounded-xl border border-primary/25 bg-card p-5"><div className="text-xs font-medium text-primary">风险与待验证</div><h2 className="mt-1 text-lg font-semibold">风险结论、低估陷阱与核心逻辑失效条件</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">资料不足会明确显示为“暂无法完整判断”，不会被显示成低风险。</p></section><CompanyWatchpointsPanel stockCode={stockCode} /><RiskResearchCard stockCode={stockCode} asOf={asOf} /><LazyDetails className="rounded-xl border bg-card" summary="查看核心逻辑失效条件与研究证据"><div className="space-y-5 border-t p-5"><CompanyThesisSummaryPanel stockCode={stockCode} /><CompanyResearchEvidencePanel stockCode={stockCode} /></div></LazyDetails></div>;
}

function CoreThesisTab({ symbol, dossier, running, reportId, onResearch, onCreatePlan }: { symbol: string; dossier: CompanyDossier | null; running: boolean; reportId?: string; onResearch: () => void; onCreatePlan: () => void }) {
  const [refreshKey, setRefreshKey] = useState(0);
  return <div className="space-y-4"><section className="rounded-xl border border-primary/25 bg-card p-5"><div className="text-xs font-medium text-primary">核心逻辑</div><h2 className="mt-1 text-lg font-semibold">公司的核心逻辑是什么，谁确认过</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">核心驱动、假设、失效条件和最新证据在这里统一呈现。AI 初步结论不会被显示为人工确认。</p></section><div key={refreshKey} className="space-y-4"><CompanyThesisSummaryPanel stockCode={symbol} /><ThesisReviewCard stockCode={symbol} /></div><LazyDetails className="rounded-xl border bg-card" summary="查看草案、历史变化与旧研究底稿"><div className="space-y-5 border-t p-5"><CompanyThesisDraftPanel stockCode={symbol} onConfirmed={() => setRefreshKey((value) => value + 1)} /><ThesisHistoryTimeline stockCode={symbol} /><ResearchTab dossier={dossier} running={running} reportId={reportId} onResearch={onResearch} onCreatePlan={onCreatePlan} /></div></LazyDetails></div>;
}

function MoreResearchTab({ symbol, asOf, rawTab, onSelectRaw, data, period, setPeriod, dividendType, setDividendType, refresh, loading, detail, snapshot, extended, dossier, running, reportId, onResearch, onCreatePlan }: { symbol: string; asOf?: string; rawTab: RawTab; onSelectRaw: (value: RawTab) => void; data: TdxSecurityOverview; period: string; setPeriod: (value: string) => void; dividendType: string; setDividendType: (value: string) => void; refresh: () => void; loading: boolean; detail: Dict; snapshot: Dict; extended: Dict; dossier: CompanyDossier | null; running: boolean; reportId?: string; onResearch: () => void; onCreatePlan: () => void }) {
  return <div className="space-y-4"><section className="rounded-xl border border-dashed bg-card p-5"><h2 className="font-semibold">更多研究</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">这里保留完整同行比较、竞争优势、资本配置、研究证据和原始资料；展开后才读取对应内容。</p></section><LazyDetails className="rounded-xl border bg-card" summary="竞争地位与竞争优势"><div className="space-y-5 border-t p-5"><LeaderQualityProfilePanel stockCode={symbol} asOf={asOf} /><MoatResearchPanel stockCode={symbol} asOf={asOf} /></div></LazyDetails><LazyDetails className="rounded-xl border bg-card" summary="资本与公司行动"><div className="border-t p-5"><CapitalAllocationFactsPanel stockCode={symbol} asOf={asOf} /></div></LazyDetails><LazyDetails className="rounded-xl border bg-card" summary="研究证据、复核与历史底稿"><div className="space-y-5 border-t p-5"><CompanyResearchEvidencePanel stockCode={symbol} /><ThesisReviewCard stockCode={symbol} /><ThesisHistoryTimeline stockCode={symbol} /><ResearchTab dossier={dossier} running={running} reportId={reportId} onResearch={onResearch} onCreatePlan={onCreatePlan} /></div></LazyDetails><LazyDetails className="rounded-xl border bg-card" summary="原始数据与方法"><div className="border-t p-5"><RawDataTab rawTab={rawTab} onSelect={onSelectRaw} data={data} symbol={symbol} period={period} setPeriod={setPeriod} dividendType={dividendType} setDividendType={setDividendType} refresh={refresh} loading={loading} detail={detail} snapshot={snapshot} extended={extended} /></div></LazyDetails></div>;
}

function ThesisTab({ symbol, dossier, running, reportId, onResearch, onCreatePlan }: { symbol: string; dossier: CompanyDossier | null; running: boolean; reportId?: string; onResearch: () => void; onCreatePlan: () => void }) {
  const [refreshKey, setRefreshKey] = useState(0);
  return <div className="space-y-5"><CompanyThesisDraftPanel stockCode={symbol} onConfirmed={() => setRefreshKey((value) => value + 1)} /><div key={refreshKey} className="space-y-5"><CompanyThesisSummaryPanel stockCode={symbol} /><ThesisReviewCard stockCode={symbol} /><ThesisHistoryTimeline stockCode={symbol} /></div><details className="rounded-xl border border-border bg-card"><summary className="cursor-pointer px-5 py-4 font-semibold">历史研究底稿</summary><div className="border-t border-border p-5"><p className="mb-4 rounded-lg border border-amber-500/30 bg-amber-500/10 p-3 text-sm text-amber-800 dark:text-amber-200">这是旧版研究资料，不代表当前正式公司核心逻辑。</p><ResearchTab dossier={dossier} running={running} reportId={reportId} onResearch={onResearch} onCreatePlan={onCreatePlan} /></div></details></div>;
}
void ThesisTab;

function RawDataTab({ rawTab, onSelect, data, symbol, period, setPeriod, dividendType, setDividendType, refresh, loading, detail, snapshot, extended }: { rawTab: RawTab; onSelect: (value: RawTab) => void; data: TdxSecurityOverview; symbol: string; period: string; setPeriod: (value: string) => void; dividendType: string; setDividendType: (value: string) => void; refresh: () => void; loading: boolean; detail: Dict; snapshot: Dict; extended: Dict }) {
  return <div className="space-y-5"><div className="overflow-x-auto"><div role="tablist" aria-label="行情与原始数据分类" className="inline-flex min-w-max rounded-lg border bg-card p-1">{RAW_TABS.map((item) => <button key={item} type="button" onClick={() => onSelect(item)} className={cn("rounded-md px-3 py-1.5 text-sm", rawTab === item ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground")}>{item}</button>)}</div></div>{rawTab === "行情" ? <KlineTab data={data} symbol={symbol} period={period} setPeriod={setPeriod} dividendType={dividendType} setDividendType={setDividendType} refresh={refresh} loading={loading} /> : null}{rawTab === "题材" ? <SectorsTab sectors={data.sectors} /> : null}{rawTab === "分红股本" ? <DividendTab detail={detail} /> : null}{rawTab === "资金结构" ? <MicroTab snapshot={snapshot} extended={extended} detail={detail} /> : null}</div>;
}

function KlineTab({ data, symbol, period, setPeriod, dividendType, setDividendType, refresh, loading }: { data: TdxSecurityOverview; symbol: string; period: string; setPeriod: (value: string) => void; dividendType: string; setDividendType: (value: string) => void; refresh: () => void; loading: boolean }) {
  const bars = useMemo(() => klineBars(data, symbol, period, dividendType), [data, dividendType, period, symbol]);
  return <section className="rounded-xl border bg-card p-5 shadow-sm"><div className="flex flex-wrap items-center gap-2 border-b pb-4"><span className="text-xs text-muted-foreground">周期</span>{[["1d", "日线"], ["1w", "周线"], ["1m", "月线"], ["5m", "5分钟"], ["15m", "15分钟"], ["30m", "30分钟"], ["60m", "60分钟"]].map(([key, label]) => <button key={key} onClick={() => setPeriod(key)} className={cn("rounded-full px-3 py-1 text-xs", period === key ? "bg-foreground text-background" : "bg-muted text-muted-foreground")}>{label}</button>)}<span className="ml-3 text-xs text-muted-foreground">复权</span>{[["front", "前复权"], ["back", "后复权"], ["none", "不复权"]].map(([key, label]) => <button key={key} onClick={() => setDividendType(key)} className={cn("rounded-full px-3 py-1 text-xs", dividendType === key ? "bg-primary text-primary-foreground" : "bg-primary/10 text-primary")}>{label}</button>)}<button onClick={refresh} disabled={loading} className="ml-auto inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-sm"><RefreshCw className={cn("h-4 w-4", loading && "animate-spin")} />更新当前K线</button></div>{bars.length ? <div className="pt-4"><CandlestickChart data={bars} height={520} /></div> : <div className="py-20 text-center text-sm text-muted-foreground">暂无该周期K线</div>}</section>;
}

function SectorsTab({ sectors }: { sectors: Dict[] }) { return <section className="rounded-xl border bg-card p-5 shadow-sm"><h2 className="font-semibold">行业、概念、地区与风格关系</h2>{sectors.length ? <div className="mt-4 flex flex-wrap gap-2">{sectors.map((row, index) => <Link key={String(row.sector_code ?? row.code ?? index)} to={`/market/sectors/${String(row.sector_code ?? row.code ?? "")}`} className="rounded-full border bg-muted/40 px-3 py-1.5 text-sm hover:border-primary hover:text-primary">{String(row.sector_name ?? row.name ?? "板块")}</Link>)}</div> : <p className="mt-4 text-sm text-muted-foreground">尚未更新板块成分缓存。</p>}</section>; }

function DividendTab({ detail }: { detail: Dict }) { const dividends = asRows(detail.dividends); const capital = asRows(detail.capital); return <section className="grid gap-5 xl:grid-cols-2"><DataTable title="历史分红送配" rows={dividends} empty="点击“刷新单股”获取分红记录" /><DataTable title="股本变化" rows={capital} empty="点击“刷新单股”获取股本记录" /></section>; }
function MicroTab({ snapshot, extended, detail }: { snapshot: Dict; extended: Dict; detail: Dict }) { const micro = asRows(detail.microstructure); return <><div className="flex items-center gap-2 rounded-xl border border-warning/30 bg-warning/5 p-3 text-sm text-warning"><AlertTriangle className="h-4 w-4 shrink-0" />部分字段为实验数据，请谨慎参考</div><section className="grid gap-5 xl:grid-cols-2"><article className="rounded-xl border bg-card p-5 shadow-sm"><h2 className="font-semibold">已确认盘口与资金字段</h2><div className="mt-4 grid grid-cols-2 gap-3">{[["内盘（手）", snapshot.Inside], ["外盘（手）", snapshot.Outside], ["主力资金（万元）", extended.Zjl], ["总买单（手）", extended.TotalBVol], ["总卖单（手）", extended.TotalSVol], ["撤买 / 撤卖", `${extended.BCancel ?? "—"} / ${extended.SCancel ?? "—"}`]].map(([label, value]) => <div key={String(label)} className="rounded-lg bg-muted/50 p-3"><div className="text-xs text-muted-foreground">{String(label)}</div><div className="mt-1 font-mono">{String(value ?? "—")}</div></div>)}</div></article><DataTable title="日内微观数组（实验数据）" rows={micro.slice(0, 50)} empty="暂无微观统计缓存" /></section></>; }

function ResearchTab({ dossier, running, reportId, onResearch, onCreatePlan }: { dossier: CompanyDossier | null; running: boolean; reportId?: string; onResearch: () => void; onCreatePlan: () => void }) {
  if (!dossier) return <section className="rounded-xl border border-dashed bg-card p-10 text-center"><FilePlus2 className="mx-auto h-9 w-9 text-primary" /><h2 className="mt-4 text-lg font-semibold">尚无研究底稿</h2><button onClick={onResearch} disabled={running} className="mt-5 inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-2.5 text-sm font-medium text-primary-foreground disabled:opacity-50">{running ? <Loader2 className="h-4 w-4 animate-spin" /> : <FilePlus2 className="h-4 w-4" />}生成深度研究</button></section>;
  return <><section className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><article className="rounded-xl border bg-card p-6"><SourceBadge status={dossier.source_status} asOf={dossier.data_as_of} /><p className="mt-4 leading-8">{dossier.overview}</p><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="rounded-xl border border-market-up/30 bg-market-up/5 p-4"><h3 className="font-semibold text-market-up">正向证据</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{dossier.bull_thesis}</p></div><div className="rounded-xl border border-market-down/30 bg-market-down/5 p-4"><h3 className="font-semibold text-market-down">风险与反证</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{dossier.bear_thesis}</p></div></div></article><div className="space-y-5"><ListCard title="催化剂" items={dossier.catalysts} /><ListCard title="风险" items={dossier.risks} /><div className="grid grid-cols-2 gap-2"><button onClick={onResearch} className="rounded-lg border px-4 py-2 text-sm font-medium">重新生成</button>{reportId ? <Link to={`/reports/${reportId}`} className="rounded-lg border px-4 py-2 text-center text-sm font-medium text-primary">查看底稿</Link> : null}</div></div></section><section className="flex flex-col justify-between gap-4 rounded-xl border border-primary/30 bg-primary/5 p-5 sm:flex-row sm:items-center"><div><div className="font-semibold">查看统一研究状态</div><p className="mt-1 text-xs text-muted-foreground">研究资格、优先级、价格关注条件与复核压力将在同一处解释。</p></div><button onClick={onCreatePlan} className="inline-flex shrink-0 items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-medium text-primary-foreground">查看机会与风险<ArrowRight className="h-4 w-4" /></button></section></>;
}

function CompanyNavigation({ symbol, companyName }: { symbol: string; companyName?: string }) {
  const [params] = useSearchParams();
  const legacyFrom = params.get("from") === "value" ? "/value" : params.get("from");
  const from = safeInternalPath(legacyFrom, "/value");
  const fromLabel = params.get("from_label") || inferReturnLabel(from);
  const sectorName = params.get("sector_name");
  return <nav aria-label="公司研究路径" className="flex flex-col gap-3 rounded-lg border bg-card px-4 py-3 text-sm sm:flex-row sm:items-center sm:justify-between"><div className="flex min-w-0 flex-wrap items-center gap-1.5 text-muted-foreground"><Link to="/value" className="hover:text-primary">价值投资</Link><ChevronRight className="h-3.5 w-3.5" />{from !== "/value" || sectorName ? <><Link to={from} className="hover:text-primary">{sectorName ? `${sectorName}龙头` : fromLabel}</Link><ChevronRight className="h-3.5 w-3.5" /></> : null}<span className="truncate text-foreground">{companyName || symbol}</span></div><div className="flex shrink-0 flex-wrap gap-2"><Link to={from} className="inline-flex items-center gap-1 rounded-md border px-3 py-1.5 hover:bg-muted"><ArrowLeft className="h-4 w-4" />返回{sectorName ? `${sectorName}龙头` : fromLabel}</Link>{from !== "/value" ? <Link to="/value" className="rounded-md border px-3 py-1.5 text-muted-foreground hover:bg-muted hover:text-foreground">返回价值投资</Link> : null}</div></nav>;
}
function LegacyCompany({ market, symbol }: { market: MarketCode; symbol: string }) { const [data, setData] = useState<CompanyDossier | null>(null); const [loading, setLoading] = useState(true); useEffect(() => { api.getCompanyDossier(market, symbol).then(setData).catch(() => setData(null)).finally(() => setLoading(false)); }, [market, symbol]); if (loading) return <WorkspacePage><CompanyNavigation symbol={symbol} /><LoadingState /></WorkspacePage>; if (!data) return <WorkspacePage><CompanyNavigation symbol={symbol} /><EmptyState title="未找到公司研究档案" body="港股、美股继续使用现有研究数据；当前缺少真实数据时不会显示示例行情。" /></WorkspacePage>; return <WorkspacePage><CompanyNavigation symbol={symbol} companyName={data.name} /><PageHeader eyebrow={`${market} / ${symbol}`} title={data.name} description={`${data.exchange} · ${data.sector_name}`} actions={<SourceBadge status={data.source_status} asOf={data.data_as_of} />} /><ResearchTab dossier={data} running={false} onResearch={() => undefined} onCreatePlan={() => undefined} /></WorkspacePage>; }

function DataTable({ title, rows, empty }: { title: string; rows: Dict[]; empty: string }) { const keys = rows.length ? Object.keys(rows[0]).slice(0, 8) : []; return <article className="overflow-hidden rounded-xl border bg-card shadow-sm"><div className="border-b p-5"><h2 className="font-semibold">{title}</h2></div>{rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-xs"><thead className="bg-muted/50 text-muted-foreground"><tr>{keys.map((key) => <th key={key} className="p-3">{key}</th>)}</tr></thead><tbody className="divide-y">{rows.map((row, index) => <tr key={index}>{keys.map((key) => <td key={key} className="max-w-40 truncate p-3 font-mono" title={String(row[key] ?? "")}>{String(row[key] ?? "—")}</td>)}</tr>)}</tbody></table></div> : <p className="p-8 text-center text-sm text-muted-foreground">{empty}</p>}</article>; }
function ListCard({ title, items }: { title: string; items: string[] }) { return <article className="rounded-xl border bg-card p-5"><h3 className="font-semibold">{title}</h3><ul className="mt-3 space-y-2 text-sm">{items.map((item) => <li key={item} className="rounded-lg bg-muted/50 p-3">{item}</li>)}</ul></article>; }
function formatDate(value: unknown) { const text = String(value ?? ""); return /^\d{8}$/.test(text) ? `${text.slice(0, 4)}-${text.slice(4, 6)}-${text.slice(6)}` : text || "—"; }
function klineBars(data: TdxSecurityOverview, symbol: string, period: string, dividendType: string): PriceBar[] { const item = data.klines.find((row) => row.period === period && row.dividend_type === dividendType); if (!item) return []; const source = asDict(item.data); const rows = (name: string) => asRows(source[name]); const map = (name: string) => new Map(rows(name).map((row) => [String(row.index), Number(row[symbol])])); const open = map("Open"), high = map("High"), low = map("Low"), close = map("Close"), volume = map("Volume"); return [...close.keys()].sort().map((time) => ({ time: time.slice(0, 10), open: open.get(time) ?? 0, high: high.get(time) ?? 0, low: low.get(time) ?? 0, close: close.get(time) ?? 0, volume: volume.get(time) ?? 0 })).filter((bar) => bar.close > 0); }
